"""Request payload for the AI bureau letter API (POST /api/clients/{client_id}/ai-letters/bureau)."""

CLIENT_SIGNATURE = "data:image/png;base64,"


def build_letter_payload(letter_template_id: int) -> dict:
    """Return the letter payload with the given letter_template_id."""
    return {
        "round_basic": "no",
        "r2_letter_to": "r2_letterto_cb",
        "selected_furnisher": [0],
        "selected_bureau_ids": [1],
        "selected_array": [815],
        "client_signature": CLIENT_SIGNATURE,
        "letter_template_id": letter_template_id,
        "which_letter": "letter_from_library",
        "create_bureau_array_1": [1],
        "create_bureau_array_2": [2],
        "create_bureau_array_3": [3],
        "check_existing_dispute": [815],
    }
